CREATE COLUMN TABLE "TEST_AP"."STC1" ("STCCode" NVARCHAR(8) NOT NULL , "Line_ID" INTEGER CS_INT DEFAULT 0 NOT NULL , "STACode" NVARCHAR(8), "STAType" INTEGER CS_INT, "TaxOnTCode" NVARCHAR(8), "TaxOnTType" INTEGER CS_INT, "EfctivRate" DECIMAL(21,6) CS_FIXED, "FmlId" INTEGER CS_INT, "CstCodeIn" NVARCHAR(20), "CstSuffix" NVARCHAR(2), "LogInstanc" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("STCCode", "Line_ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."STC1" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$STACode$STAType$','STACode','STAType'));
CREATE INDEX "STC1_STACode" ON "TEST_AP"."STC1" ( "STACode" ASC, "STAType" ASC )